import{createHash}from"node:crypto";import{DEFAULT_EVE_SANDBOX_IMAGE}from"#execution/sandbox/bindings/eve-image.js";const DEFAULT_DOCKER_SANDBOX_IMAGE=DEFAULT_EVE_SANDBOX_IMAGE;function resolveDockerSandboxOptions(e={}){return{env:e.env??{},image:e.image??DEFAULT_DOCKER_SANDBOX_IMAGE,pullPolicy:e.pullPolicy??`if-not-present`}}function createDockerSandboxOptionsHash(e){return createHash(`sha256`).update(JSON.stringify(dockerOptionsForHash(e))).digest(`hex`).slice(0,20)}function dockerOptionsForHash(e){return{env:sortStringRecord(e.env),image:e.image,pullPolicy:e.pullPolicy}}function sortStringRecord(e){return Object.fromEntries(Object.entries(e).sort(([e],[t])=>e.localeCompare(t)))}export{DEFAULT_DOCKER_SANDBOX_IMAGE,createDockerSandboxOptionsHash,resolveDockerSandboxOptions};